  'update',
  $payload${"moduleId":"safety-qc","revisionType":"quiz","title":"Evaluación: Artefacto de Estímulo Excesivo","quizTopicId":"stimulus-artifact","passScore":70,"maxAttempts":null,"shuffleQuestions":true,"shuffleOptions":true,"questions":[{"id":"stimart-q1","sortOrder":0,"type":"single","difficulty":"basic","stem":"Tras el estímulo, una deflexión enorme cubre el inicio del CMAP y no se puede marcar la latencia. ¿Cómo llama la lección a ese problema y qué impide medir?","options":[{"id":"stimart-q1-a","text":"Artefacto de estímulo excesivo: oculta el inicio del potencial y deja la latencia ilegible.","isCorrect":true},{"id":"stimart-q1-b","text":"Interferencia de 60 Hz: una senoide continua durante todo el barrido.","isCorrect":false},{"id":"stimart-q1-c","text":"Bloqueo de conducción: la amplitud proximal cae más del 50 %.","isCorrect":false},{"id":"stimart-q1-d","text":"Dispersión temporal: el potencial proximal dura el doble, con el inicio bien visible.","isCorrect":false}],"explanation":"El artefacto de estímulo tapa el takeoff. Sin un inicio claro, la latencia no se mide.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"stimart-q2","sortOrder":1,"type":"multiple","difficulty":"intermediate","stem":"El inicio del SNAP queda tapado por el artefacto de estímulo. ¿Qué dos maniobras lista la lección para este problema?","options":[{"id":"stimart-q2-a","text":"Girar el ánodo del estimulador.","isCorrect":true},{"id":"stimart-q2-b","text":"Reducir la duración del estímulo, o pellizcar la piel entre estimulador y electrodo activo.","isCorrect":true},{"id":"stimart-q2-c","text":"Desconectar la cama eléctrica como maniobra específica de este artefacto.","isCorrect":false},{"id":"stimart-q2-d","text":"Alejar la tierra hasta el hombro contralateral.","isCorrect":false}],"explanation":"La lección indica poner la tierra entre estimulador y registro, girar el ánodo, acortar la duración del estímulo o pellizcar la piel entre ambos. Alejar la tierra al hombro contrario empeora el circuito.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]},{"id":"stimart-q3","sortOrder":2,"type":"single","difficulty":"advanced","stem":"Hay que distinguir dos artefactos en la misma mano. El barrido muestra una cola aguda justo después del estímulo, que cubre el inicio, sin una senoide de 60 Hz. ¿Qué maniobra elige primero?","options":[{"id":"stimart-q3-a","text":"Acortar la duración del estímulo y rotar el ánodo.","isCorrect":true},{"id":"stimart-q3-b","text":"Promediar 100 trazos dejando el estímulo en 1 ms.","isCorrect":false},{"id":"stimart-q3-c","text":"Subir el filtro de baja a 500 Hz para borrar el inicio biológico.","isCorrect":false},{"id":"stimart-q3-d","text":"Aumentar la intensidad un 50 % por encima del artefacto.","isCorrect":false}],"explanation":"Una cola inmediata al shock es artefacto de estímulo. Subir la intensidad o alargar el pulso lo agranda. El 60 Hz, en cambio, es una oscilación continua.\n\n📚 Referencia: London ZN. Safety and pain in electrodiagnostic studies. Muscle & Nerve (2017). https://doi.org/10.1002/mus.25421","citations":[{"authors":"London ZN","title":"Safety and pain in electrodiagnostic studies","journal":"Muscle & Nerve","year":2017,"url":"https://doi.org/10.1002/mus.25421"}]},{"id":"stimart-q4","sortOrder":3,"type":"single","difficulty":"intermediate","stem":"La tierra está sobre el electrodo activo y el artefacto de estímulo invade el SNAP. ¿Hacia dónde la mueve la lección?","options":[{"id":"stimart-q4-a","text":"La separa del registro y la deja entre el estimulador y el electrodo activo.","isCorrect":true},{"id":"stimart-q4-b","text":"La pega al cátodo para que el artefacto “se reste”.","isCorrect":false},{"id":"stimart-q4-c","text":"La coloca distal a G2, sobre la yema del dedo.","isCorrect":false},{"id":"stimart-q4-d","text":"La retira del paciente y estudia sin tierra.","isCorrect":false}],"explanation":"Quitar la tierra aumenta el ruido. La posición que enseña la lección es entre estimulador y registro, no encima del electrodo activo.\n\n📚 Referencia: Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","citations":[{"authors":"Preston DC, Shapiro BE","title":"Electromyography and Neuromuscular Disorders (4th ed)","journal":"Elsevier","year":2021,"url":"https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5"}]}],"examQuestions":[{"module_id":"safety-qc","topic_id":"stimulus-artifact","topic_name":"Artefacto de Estímulo Excesivo","island_name":"EMG","stem":"En el mediano motor a 8 cm, el shock de 0.5 ms produce una deflexión que no vuelve a la línea de base antes del CMAP. La latencia de inicio no se puede marcar. No hay oscilación de 60 Hz.","difficulty":2,"is_critical":false,"findings":[{"type":"LAT","label":"Latencia de inicio del CMAP","value":"Ilegible; el artefacto cubre el takeoff"},{"type":"SIGN","label":"Duración del estímulo","value":"0.5 ms"}],"options":[{"text":"Acortar la duración del estímulo, rotar el ánodo y colocar la tierra entre estímulo y G1.","is_correct":true,"feedback":"Son las correcciones del artefacto de estímulo. Un pulso de 0.5 ms es largo para un motor rutinario."},{"text":"Informar latencia distal de 0.5 ms, medida sobre el artefacto.","is_correct":false,"feedback":"Medir sobre el artefacto acorta falsamente la latencia."},{"text":"Desconectar la cama y abrasir la piel como única acción.","is_correct":false,"feedback":"Eso corresponde al 60 Hz, que aquí no es el patrón descrito."},{"text":"Subir a 1 ms de duración para obtener un CMAP más nítido.","is_correct":false,"feedback":"Alargar el pulso agranda el artefacto de estímulo."}],"pearl":"Si no ves el inicio, no inventes la latencia. Acorta el pulso, gira el ánodo y ordena la tierra.","source_reference":"Preston DC, Shapiro BE. Electromyography and Neuromuscular Disorders (4th ed). Elsevier (2021). https://www.elsevier.com/books/electromyography-and-neuromuscular-disorders/preston/978-0-323-66180-5","tags":["safety-qc","stimulus-artifact"],"status":"DRAFT"}]}$payload$::jsonb,
